import React from "react";
import { CheckCircle } from "lucide-react";

const CryptoFlow = ({ currentStep = 0, mode = "hybrid" }) => {
  const isRSA = mode === "rsa";

  const steps = isRSA
    ? [
        { label: "RSA KEYGEN", sub: "2048-bit" },
        { label: "ENCRYPT KEY", sub: "OAEP" },
        { label: "AES SESSION", sub: "256-GCM" },
        { label: "UPLOAD", sub: "MinIO" }
      ]
    : [
        { label: "EPHEMERAL", sub: "X25519" },
        { label: "ENCAPSULATE", sub: "Shared Secret" },
        { label: "HKDF", sub: "SHA-256" },
        { label: "AES", sub: "256-GCM" },
        { label: "UPLOAD", sub: "MinIO" }
      ];

  const activeColor = isRSA ? "#a855f7" : "#00ff9d";

  return (
    <div className="relative mt-6">
      {/* line */}
      <div className="absolute top-6 left-0 w-full h-[2px] bg-gray-800"/>
      <div
        className="absolute top-6 left-0 h-[2px] transition-all"
        style={{
          width: `${(currentStep / steps.length) * 100}%`,
          background: activeColor
        }}
      />

      <div className="flex justify-between">
        {steps.map((s, i) => {
          const done = i + 1 <= currentStep;
          return (
            <div key={i} className="flex flex-col items-center w-24">
              <div
                className="w-12 h-12 rounded-full border flex items-center justify-center"
                style={{
                  borderColor: done ? activeColor : "#333",
                  color: done ? activeColor : "#555"
                }}
              >
                {done ? <CheckCircle size={18}/> : i + 1}
              </div>

              <p className="text-[10px] mt-2 text-gray-300">{s.label}</p>
              <p className="text-[9px]" style={{ color: activeColor }}>
                {s.sub}
              </p>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CryptoFlow;
